def apply(g):
    """Ajoute es et ar aux structures de contenu.py et au dictionnaire d'interface."""
    for name in ("SITE_TITLE", "BIO", "DISCLAIMER"):
        g[name].update(globals()[name])
    for a, t in zip(g["AXES"], AXES):
        a.update(t)
    for k, t in TOPICS.items():
        g["TOPICS"][k].update(t)
    for p in g["PUBLICATIONS"]:
        t = PUBS[p["slug"]]
        for field, val in t.items():
            if field == "figures":
                for (_, labels), extra in zip(p["figures"], val):
                    labels.update(extra)
            else:
                p[field].update(val)
    g["UI"].update(UI)
    for lang, extra in UI_EXTRA.items():
        g["UI"][lang].update(extra)
